// Finds rows that need tags in every listed tab and builds one prompt per row. Nothing is written here.
const cfg = $('Config').first().json;
const tabItems = $('Tabs').all().map(i => i.json);
const results = $input.all().map(i => i.json);
const nk = s => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
const letters = n => { let s = ''; n += 1; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; };
const yes = v => /^(yes|true|1)$/i.test(String(v || '').trim());
const cell = (r, i) => (i < 0 || r[i] == null ? '' : String(r[i]).trim());
const clean = t => String(t).replace(/[^\p{L}\p{N} \-']/gu, '').replace(/\s+/g, ' ').trim();
const want = String(cfg.sku || '').trim().toUpperCase();
const capTab = Number(cfg.perTab) || 20, maxRows = Number(cfg.maxRows) || 40;
const out = [], skipped = [];
tabItems.forEach((t, k) => {
  if (out.length >= maxRows) return;
  const res = results[k] || {};
  if (res.error || !res.values) { skipped.push({ tab: t.tab, reason: 'could not read the tab' }); return; }
  const rows = res.values;
  const hk = (rows[0] || []).map(nk);
  const ix = name => hk.indexOf(nk(name));
  const skuCol = hk.lastIndexOf('productno'), titleCol = ix('Title_Etsy'), tagCol = ix('Tags_Etsy');
  if (skuCol < 0 || titleCol < 0 || tagCol < 0) { skipped.push({ tab: t.tab, reason: 'missing Product No., Title_Etsy or Tags_Etsy column' }); return; }
  const kwCol = ix('Keywords (Luna)'), readyCol = ix('Etsy_ready_to_post'), listCol = ix('Etsy_listing_id'), statCol = ix('Etsy_status');
  let n = 0;
  for (let i = 1; i < rows.length && n < capTab && out.length < maxRows; i++) {
    const r = rows[i] || [];
    const sku = cell(r, skuCol);
    if (!sku || !cell(r, titleCol)) continue;
    if (want && sku.toUpperCase() !== want) continue;
    if (!want) {
      if (cfg.onlyFlagged !== false && !yes(cell(r, readyCol))) continue;
      if (cell(r, listCol) || cell(r, statCol)) continue;
    }
    const existing = [];
    cell(r, tagCol).split(/[,;\n|]+/).forEach(x => { x = clean(x); if (x && x.length <= 20 && !existing.some(y => y.toLowerCase() === x.toLowerCase())) existing.push(x); });
    if (existing.length >= 13) continue;
    const prompt = [
      'You write Etsy search tags for a handmade natural stone product listing.',
      'Return ONLY a JSON array of ' + (13 - existing.length + 20) + ' candidate tags as strings. No explanation, no markdown.',
      'Rules: each tag is 2 to 20 characters including spaces; use only letters, numbers, spaces, hyphens and apostrophes; no duplicates; no brand names; no words like "cheap" or "sale".',
      'Tags are short phrases a buyer would type into Etsy: material, stone name, product type, style, room, use. Mix 2 and 3 word phrases.',
      'Every tag must add a NEW idea (stone colour, stone name, shape, style, room, use, gift). Never give two tags that only swap words for the same product (for example bath, bathtub, tub, sink, basin, fireplace, mantel).',
      'ACCURACY: only use a stone name, colour, finish or shape that is written in the product title or the owner keyword. Never guess or invent one. If the title does not say it, do not use it.',
      'SEARCHABLE: prefer tags that name the product itself together with one specific attribute from the title. Avoid vague tags like statement piece, design, feature or silhouette.',
      'STONE NAME LIMIT: use any one stone name (for example Crema Marfil) in at most 3 tags. The other tags must be about the product type, style, room or use.',
      'NO NUMBERS: never put sizes, measurements or digits in a tag (no "59 inch", no "47 inch height").',
      'SPELLING: if the title and the owner keyword spell a stone name differently (for example Lepanto and Levanto), use ONLY the spelling in the product title. Never mix two spellings.',
      'Do not repeat or closely copy these existing tags: ' + (existing.length ? existing.join(', ') : '(none)'),
      'Product title: ' + cell(r, titleCol),
      'Product type (sheet tab): ' + t.tab,
      'Main keyword from the owner: ' + (cell(r, kwCol) || '(none)')
    ].join('\n');
    out.push({ json: { row: i + 2, sku, title: cell(r, titleCol), existing, prompt, tab: t.tab, tagCol: letters(tagCol) } });
    n++;
  }
});
if (!out.length) return [{ json: { noRows: true, skipped, message: 'no rows need tags in: ' + tabItems.map(t => t.tab).join(', ') } }];
return out;

const sd = $getWorkflowStaticData('global'); sd.lockUntil = 0;
const j = $input.first().json;
return [{ json: { done: true, message: j.problem || j.message || 'nothing to do' } }];

const rows = $('Pick Rows').all().map(i => i.json);
const outs = $input.all().map(i => i.json);
const clean = t => String(t).replace(/[^\p{L}\p{N} \-']/gu, '').replace(/\s+/g, ' ').trim();
const results = rows.map((r, i) => {
  const g = outs[i] || {};
  if (g.error) return { row: r.row, sku: r.sku, tab: r.tab, tagCol: r.tagCol, added: 0, tags: r.existing, note: 'Gemini error: ' + (typeof g.error === 'string' ? g.error : JSON.stringify(g.error)).slice(0, 120) };
  const text = g.content && g.content.parts ? g.content.parts.map(x => x.text || '').join('') : String(g.text || g.output || '');
  let cand = [];
  const m = text.match(/\[[\s\S]*\]/);
  if (m) { try { cand = JSON.parse(m[0]); } catch (e) { cand = []; } }
  if (!Array.isArray(cand)) cand = [];
  const SYN = { Bathtub: ['bath','baths','bathtub','bathtubs','tub','tubs','bathing'], Sink: ['sink','sinks','basin','basins','washbasin','bowl','vessel'], 'Marble+ Basin': ['sink','sinks','basin','basins','washbasin','bowl','vessel'], Fireplace: ['fireplace','fireplaces','mantel','mantle','surround','hearth'], Vanity: ['vanity','vanities','sink','cabinet','basin'], Table: ['table','tables','tabletop','top'], 'Marble+ ConsoleTable': ['table','tables','console','consoles'], Bench: ['bench','benches','seat','seating'], Fountain: ['fountain','fountains','waterfall'], Planter: ['planter','planters','pot','pots','flowerpot'], Lamppost: ['lamp','lampost','lamppost','post','light'], Statue: ['statue','statues','sculpture','sculptures','figure','figurine'], Animal: ['statue','statues','sculpture','sculptures','animal','figure'], Carving: ['carving','carvings','carved','relief','sculpture'], Moulding: ['moulding','molding','mouldings','moldings','trim','baseboard','cornice','skirting'], OutdoorCornice: ['cornice','moulding','molding','trim'], DoorSurround: ['door','surround','frame','trim','doorway'], WindowSurround: ['window','surround','frame','trim','sill'], Columns: ['column','columns','pillar','pillars'], Balustrade: ['balustrade','balustrades','baluster','balusters','railing','railings','rail','rails','handrail','handrails','spindle','spindles','post','posts','banister','banisters','stair','stairs','staircase'], Stairs: ['stair','stairs','staircase','steps','step'], MarbleRangeHood: ['hood','hoods','range','rangehood','vent'], MarbleSlab: ['slab','slabs'], BookMatchedSlabs: ['slab','slabs','bookmatched','book','matched'], StoneMosaicTile: ['mosaic','mosaics','tile','tiles'], MarbleMedallion: ['medallion','medallions','inlay'], 'Wall-Coverings': ['wall','walls','panel','panels','cladding','covering','coverings'], Wainscoting: ['wainscoting','wainscot','wall','panel','panels'], 'Exterior-Wall-Decoration': ['wall','walls','exterior','decoration','relief'], '2026Instock': [] };
  const syn = new Set(SYN[r.tab] || []);
  const GEN = new Set(['bathroom', 'master', 'fixture', 'home', 'house', 'decor', 'design', 'piece', 'feature', 'room']);
  const meaningful = t => t.toLowerCase().split(/[\s-]+/).some(w => w && !syn.has(w) && !GEN.has(w));
  const sig = t => t.toLowerCase().split(/[\s-]+/).filter(w => w && !syn.has(w)).join(' ') || t.toLowerCase();
  const tags = r.existing.slice();
  const have = new Set(tags.map(x => x.toLowerCase()));
  const sigs = new Set(tags.map(sig));
  const STOPW = new Set(['marble', 'stone', 'natural', 'carved', 'luxury', 'custom', 'solid', 'handmade', 'hand', 'handcrafted', 'modern', 'classic', 'premium', 'large', 'outdoor', 'indoor', 'the', 'and', 'for', 'with', 'of', 'a', 'in']);
  const dist = t => t.toLowerCase().split(/[\s-]+/).filter(w => w && !syn.has(w) && !GEN.has(w) && !STOPW.has(w));
  const wc = {}; tags.forEach(t => dist(t).forEach(w => { wc[w] = (wc[w] || 0) + 1; }));
  let added = 0;
  for (const c of cand) { if (tags.length >= 13) break; const t = clean(c); if (t.length < 2 || t.length > 20 || have.has(t.toLowerCase()) || /\d/.test(t) || !meaningful(t) || sigs.has(sig(t)) || dist(t).some(w => (wc[w] || 0) >= 3)) continue; tags.push(t); have.add(t.toLowerCase()); sigs.add(sig(t)); dist(t).forEach(w => { wc[w] = (wc[w] || 0) + 1; }); added++; }
  return { row: r.row, sku: r.sku, tab: r.tab, tagCol: r.tagCol, added, tags, note: tags.length < 13 ? 'only ' + tags.length + ' tags' : '' };
});
const cfg = $('Config').first().json;
const data = results.filter(x => x.added > 0).map(x => ({ range: "'" + String(x.tab).replace(/'/g, "''") + "'!" + x.tagCol + x.row, values: [[x.tags.join(', ')]] }));
const byTab = {}; results.forEach(x => { byTab[x.tab] = (byTab[x.tab] || 0) + 1; });
return [{ json: { dryRun: cfg.dryRun !== false, byTab, rows: results.length, withTags13: results.filter(x => x.tags.length === 13).length, needReview: results.filter(x => x.tags.length < 13).length, results, body: { valueInputOption: 'RAW', data } } }];

const sd = $getWorkflowStaticData('global'); sd.lockUntil = 0;
const { body, ...rest } = $input.first().json;
return [{ json: { message: 'DRY RUN: nothing was written to the sheet. Set dryRun to false in Config to save these tags into Tags_Etsy.', ...rest, cellsToWrite: (body.data || []).length } }];

const sd = $getWorkflowStaticData('global'); sd.lockUntil = 0;
const w = $input.first().json;
const v = $('Validate Tags').first().json;
const { body, ...rest } = v;
return [{ json: { ...rest, dryRun: false, cellsUpdated: w.totalUpdatedCells || 0, sheetError: w.error || null } }];

// One run at a time. The lock expires after 45 minutes so a crashed run cannot block the next ones.
const sd = $getWorkflowStaticData('global');
const now = Date.now();
if (sd.lockUntil && sd.lockUntil > now) return [{ json: { locked: true, until: new Date(sd.lockUntil).toISOString() } }];
sd.lockUntil = now + 45 * 60 * 1000;
return [{ json: { locked: false } }];

const cfg = $('Config').first().json;
const ALL = ['2026Instock','Animal','Balustrade','Bathtub','Bench','BookMatchedSlabs','Carving','Columns','DoorSurround','Exterior-Wall-Decoration','Fireplace','Fountain','Lamppost','Marble+ Basin','Marble+ ConsoleTable','MarbleMedallion','MarbleRangeHood','MarbleSlab','Moulding','OutdoorCornice','Planter','Sink','Stairs','Statue','StoneMosaicTile','Table','Vanity','Wainscoting','Wall-Coverings','WindowSurround'];
const raw = String(cfg.tabs || '').trim();
const tabs = raw.toUpperCase() === 'ALL' ? ALL : raw.split(',').map(s => s.trim()).filter(Boolean);
return tabs.map(t => ({ json: { tab: t, url: 'https://sheets.googleapis.com/v4/spreadsheets/' + cfg.docId + '/values/' + encodeURIComponent("'" + t.replace(/'/g, "''") + "'!2:1500") + '?majorDimension=ROWS&valueRenderOption=UNFORMATTED_VALUE' } }));
